import java.util.Scanner;
public class VendingMachine2
{
	public static void main(String[] args)
	{
		//Khatwa 1: Taayyin al-thawabit allati nahtaajuha li hadha al-barnamaj
		final int PENNIES_PER_DOLLAR = 100;
		final int PENNIES_PER_QUARTER = 25;
		final int PENNIES_PER_DIME = 10;
		final int PENNIES_PER_NICKEL = 5;
		//Khatwa 2: Iqra' qimat al-waraqa wa thaman al-artikel
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-waraqa bi ad-dular (1 = $1, 5 = $5, etc.): ");
		int billValue = scan.nextInt();
		System.out.println("Adkhil thaman al-artikel bi santimat: ");
		int itemPrice = scan.nextInt();
		scan.close();
		//Khatwa 3: Ihsab al-baqiya almawjuda
		int changeDue = PENNIES_PER_DOLLAR * billValue - itemPrice;
		//Khatwa 4: Ihsab 'adad al-rub'iyat fi al-baqiya wa tahdith al-baqiya ba'da isqat al-rub'iyat
		int quarters = changeDue / PENNIES_PER_QUARTER;
		changeDue = changeDue % PENNIES_PER_QUARTER;
		//Khatwa 5: Ihsab 'adad al-daymat fi al-baqiya wa tahdith al-baqiya ba'da isqat al-daym
		int dimes = changeDue / PENNIES_PER_DIME;
		changeDue = changeDue % PENNIES_PER_DIME;
		//Khatwa 6: Ihsab 'adad al-nikil fi al-baqiya al-mutabqi
		int nickels = changeDue / PENNIES_PER_NICKEL;
		//Khatwa 7: Ard al-nateeja
		System.out.println("Al-baqiya tatakawan min:"); 
		System.out.println(quarters + " rub'iyat");
		System.out.println(dimes + " daymat"); 
		System.out.println(nickels + " nikels");
	}
}
